 // optional: an online payment link (Stripe, Lemon Squeezy...) opened at checkout\n  dataUrl: \"\"              // optional: link to YOUR data (Google Sheet CSV or JSON) — see the guide\n};\n\n/* ===== 2. YOUR CONTENT — edit me (texts, products, prices, opening hours) ===== */\nconst DATA = {\n  \"hero\": {\n    \"eyebrow\": \"First week free · No contract\",\n    \"title\": \"Build the <em>stronger</em> you.\",\n    \"sub\": \"Strength, cardio and classes for every level, with coaches who push you and a community that cheers you on.\",\n    \"cta1\": \"Join now\",\n    \"cta2\": \"See classes\",\n    \"tagline\": \"Train hard. Feel great.\",\n    \"emojis\": [\n      \"🏋️\",\n      \"🥊\",\n      \"🧘\",\n      \"🚴\",\n      \"🏃\",\n      \"💪\"\n    ],\n    \"chips\": [\n      \"🔥 40+ classes / week\",\n      \"💪 Expert coaches\"\n    ]\n  },\n  \"features\": [\n    {\n      \"icon\": \"🏋️\",\n      \"title\": \"Modern equipment\",\n      \"text\": \"Everything you need.\"\n    },\n    {\n      \"icon\": \"👟\",\n      \"title\": \"Expert coaches\",\n      \"text\": \"Personal training available.\"\n    },\n    {\n      \"icon\": \"🕒\",\n      \"title\": \"Open 6am – midnight\",\n      \"text\": \"Train when it suits you.\"\n    },\n    {\n      \"icon\": \"🚿\",\n      \"title\": \"Spa & showers\",\n      \"text\": \"Recover in style.\"\n    }\n  ],\n  \"sections\": {\n    \"catalogTitle\": \"Weekly classes\",\n    \"catalogSub\": \"All levels welcome. Pick a class and book your spot.\"\n  },\n  \"items\": [\n    {\n      \"id\": \"f1\",\n      \"name\": \"Strength & conditioning\",\n      \"category\": \"Strength\",\n      \"price\": 12,\n      \"desc\": \"Full-body barbell training.\",\n      \"emoji\": \"🏋️\",\n      \"per\": \"class\",\n      \"meta\": [\n        \"Mon · Wed 18:00\",\n        \"60 min\"\n      ]\n    },\n    {\n      \"id\": \"f2\",\n      \"name\": \"Boxing fundamentals\",\n      \"category\": \"Combat\",\n      \"price\": 12,\n      \"desc\": \"Technique, pads and cardio.\",\n      \"emoji\": \"🥊\",\n      \"per\": \"class\",\n      \"meta\": [\n        \"Tue · Thu 19:00\",\n        \"60 min\"\n      ],\n      \"badge\": \"Popular\"\n    },\n    {\n      \"id\": \"f3\",\n      \"name\": \"Vinyasa yoga\",\n      \"category\": \"Mind & body\",\n      \"price\": 10,\n      \"desc\": \"Flow, stretch and breathe.\",\n      \"emoji\": \"🧘\",\n      \"per\": \"class\",\n      \"meta\": [\n        \"Daily 07:00\",\n        \"60 min\"\n      ]\n    },\n    {\n      \"id\": \"f4\",\n      \"name\": \"Spin cycling\",\n      \"category\": \"Cardio\",\n      \"price\": 10,\n      \"desc\": \"High-energy ride to music.\",\n      \"emoji\": \"🚴\",\n      \"per\": \"class\",\n      \"meta\": [\n        \"Mon · Fri 18:30\",\n        \"45 min\"\n      ]\n    },\n    {\n      \"id\": \"f5\",\n      \"name\": \"HIIT burn\",\n      \"category\": \"Cardio\",\n      \"price\": 10,\n      \"desc\": \"Intervals that torch calories.\",\n      \"emoji\": \"🏃\",\n      \"per\": \"class\",\n      \"meta\": [\n        \"Sat 10:00\",\n        \"40 min\"\n      ],\n      \"badge\": \"New\"\n    },\n    {\n      \"id\": \"f6\",\n      \"name\": \"Pilates core\",\n      \"category\": \"Mind & body\",\n      \"price\": 10,\n      \"desc\": \"Posture and deep core.\",\n      \"emoji\": \"🤸\",\n      \"per\": \"class\",\n      \"meta\": [\n        \"Wed · Sat 09:00\",\n        \"50 min\"\n      ]\n    }\n  ],\n  \"reviews\": [\n    {\n      \"name\": \"Layla B.\",\n      \"role\": \"Member\",\n      \"text\": \"Lost 12 kg in 4 months. The coaches are incredible.\",\n      \"stars\": 5\n    },\n    {\n      \"name\": \"Mark D.\",\n      \"role\": \"Member\",\n      \"text\": \"Clean gym, great classes, friendly vibe.\",\n      \"stars\": 5\n    },\n    {\n      \"name\": \"Rami H.\",\n      \"role\": \"Member\",\n      \"text\": \"Best decision I made this year.\",\n      \"stars\": 5\n    }\n  ],\n  \"hours\": [\n    {\n      \"day\": \"Mon – Fri\",\n      \"time\": \"06:00 – 00:00\"\n    },\n    {\n      \"day\": \"Sat – Sun\",\n      \"time\": \"08:00 – 22:00\"\n    }\n  ],\n  \"contact\": {\n    \"address\": \"Forge Street 7, Your City\",\n    \"phone\": \"+000 000 0000\",\n    \"email\": \"join@example.com\"\n  },\n  \"extra\": {\n    \"plans\": {\n      \"title\": \"Membership plans\",\n      \"sub\": \"Simple pricing. Cancel any time.\",\n      \"list\": [\n        {\n          \"name\": \"Basic\",\n          \"price\": 29,\n          \"per\": \"month\",\n          \"features\": [\n            \"Gym floor access\",\n            \"Locker room\",\n            \"2 classes / month\"\n          ],\n          \"cta\": \"Choose Basic\"\n        },\n        {\n          \"name\": \"Pro\",\n          \"price\": 49,\n          \"per\": \"month\",\n          \"features\": [\n            \"Everything in Basic\",\n            \"Unlimited classes\",\n            \"1 PT session / month\",\n            \"Sauna & spa\"\n          ],\n          \"hl\": true,\n          \"cta\": \"Choose Pro\"\n        },\n        {\n          \"name\": \"Elite\",\n          \"price\": 89,\n          \"per\": \"month\",\n          \"features\": [\n            \"Everything in Pro\",\n            \"4 PT sessions / month\",\n            \"Nutrition plan\",\n            \"Guest passes\"\n          ],\n          \"cta\": \"Choose Elite\"\n        }\n      ]\n    }\n  },\n  \"form\": {\n    \"title\": \"Join the club\",\n    \"sub\": \"Leave your details and we will set up your free first week.\",\n    \"button\": \"Claim my free week\",\n    \"cta\": \"Book this class\",\n    \"fields\": [\n      {\n        \"name\": \"name\",\n        \"label\": \"Your name\",\n        \"type\": \"text\",\n        \"required\": true\n      },\n      {\n        \"name\": \"phone\",\n        \"label\": \"Phone / WhatsApp\",\n        \"type\": \"tel\",\n        \"required\": true\n      },\n      {\n        \"name\": \"item\",\n        \"label\": \"Interested in\",\n        \"type\": \"select\",\n        \"options\": [\n          \"Basic membership\",\n          \"Pro membership\",\n          \"Elite membership\",\n          \"A class\",\n          \"Personal training\"\n        ]\n      },\n      {\n        \"name\": \"goal\",\n        \"label\": \"Your goal\",\n        \"type\": \"select\",\n        \"options\": [\n          \"Lose weight\",\n          \"Build muscle\",\n          \"Get fit\",\n          \"Learn a sport\"\n        ]\n      },\n      {\n        \"name\": \"notes\",\n        \"label\": \"Anything we should know?\",\n        \"type\": \"textarea\",\n        \"wide\": true\n      }\n    ]\n  }\n};\n\n/* ============================================================================\n   3. ENGINE — you normally do NOT need to change anything below this line.\n   It reads CONFIG and DATA (above) and builds the whole website.\n   ============================================================================ */\n(function () {\n  'use strict';\n  var $ = function (s, r) { return (r || document).querySelector(s); };\n  var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };\n  function esc(s) { return String(s == null ? '' : s).replace(/[&<>\"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]; }); }\n  function money(n) { return CONFIG.currency + Number(n).toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 2 }); }\n  var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;\n  var fine = window.matchMedia && matchMedia('(hover:hover) and (pointer:fine)').matches;\n  var items = DATA.items.slice(), cat = 'All', q = '', cart = {}, CK = 'cart-' + CONFIG.brand;\n  try { cart = JSON.parse(localStorage.getItem(CK)) || {}; } catch (e) { cart = {}; }\n\n  function toast(m) { var t = $('#tst'); t.textContent = m; t.classList.add('on'); clearTimeout(toast.t); toast.t = setTimeout(function () { t.classList.remove('on'); }, 2800); }\n\n  /* ---------- send an order / booking / enquiry ----------\n     Order of preference: your form service (CONFIG.formAction) -> WhatsApp -> email.\n     Nothing is sent anywhere unless you fill in one of them in CONFIG. */\n  function send(subject, lines, done) {\n    var text = subject + '\\n\\n' + lines.join('\\n');\n    if (CONFIG.formAction) {\n      fetch(CONFIG.formAction, { method: 'POST', headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' }, body: JSON.stringify({ subject: subject, message: text }) })\n        .then(function (r) { if (!r.ok) throw 0; toast('Thank you! We received your request.'); if (done) done(); })\n        .catch(function () { toast('Could not send. Please try WhatsApp or email.'); });\n    } else if (CONFIG.whatsapp) {\n      window.open('https://wa.me/' + String(CONFIG.whatsapp).replace(/\\D/g, '') + '?text=' + encodeURIComponent(text), '_blank'); if (done) done();\n    } else if (CONFIG.email) {\n      window.location.href = 'mailto:' + CONFIG.email + '?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(text); if (done) done();\n    } else { toast('Demo mode: add your WhatsApp number or email in CONFIG (top of the file) to receive requests.'); }\n  }\n\n  /* ---------- text, hero, features ---------- */\n  function renderTexts() {\n    document.title = CONFIG.brand + ' — ' + DATA.hero.tagline;\n    $$('[data-brand]').forEach(function (e) { e.textContent = CONFIG.brand; });\n    $('#hEb').textContent = DATA.hero.eyebrow; $('#hT').innerHTML = DATA.hero.title; $('#hS').textContent = DATA.hero.sub;\n    $('#hC1').textContent = DATA.hero.cta1; $('#hC2').textContent = DATA.hero.cta2;\n    $('#fts').innerHTML = DATA.features.map(function (f, i) { return '<div class=\"ft rv\" style=\"--d:' + (i * .07) + 's\"><i>' + esc(f.icon) + '</i><b>' + esc(f.title) + '</b><span>' + esc(f.text) + '</span></div>'; }).join('');\n    $('#cHead').innerHTML = '<h2>' + DATA.sections.catalogTitle + '</h2><p>' + esc(DATA.sections.catalogSub) + '</p>';\n    $('#rvs').innerHTML = DATA.reviews.map(function (r, i) { return '<div class=\"rvw rv tl\" style=\"--d:' + (i * .08) + 's\"><div class=\"st\">' + '★★★★★'.slice(0, r.stars || 5) + '</div><p>“' + esc(r.text) + '”</p><b>' + esc(r.name) + '</b><span>' + esc(r.role) + '</span></div>'; }).join('');\n    var c = DATA.contact, h = (DATA.hours || []).map(function (x) { return '<div><span>' + esc(x.day) + '</span><span>' + esc(x.time) + '</span></div>'; }).join('');\n    $('#ctc').innerHTML = '<div class=\"info\"><div class=\"ib\"><b>Visit us</b>' + esc(c.address) + '</div><div class=\"ib\"><b>Contact</b>' + esc(c.phone) + '<br>' + esc(c.email) + '</div>' + (h ? '<div class=\"ib\"><b>Opening hours</b><div>' + h + '</div></div>' : '') + '</div>';\n    $('#foot').innerHTML = '<div><b>' + esc(CONFIG.brand) + '</b><br>' + esc(DATA.hero.tagline) + '</div><div>' + esc(c.address) + '<br>' + esc(c.phone) + '</div><div>&copy; ' + new Date().getFullYear() + ' ' + esc(CONFIG.brand) + '</div>';\n  }\n  function renderScene() {\n    var h = DATA.hero, em = h.emojis, it = items, t = CONFIG.hero3d, sc = $('#scene');\n    if (t === 'ring') {\n      sc.innerHTML = '<div class=\"ring\"><div class=\"rgi\">' + em.slice(0, 6).map(function (e, i) { var x = it[i]; return '<div class=\"rc\" style=\"transform:rotateY(' + i * 60 + 'deg) translateZ(var(--rz))\"><span>' + e + '</span><b>' + esc(x ? x.name : '') + '</b></div>'; }).join('') + '</div></div>';\n    } else if (t === 'cube') {\n      sc.innerHTML = '<div class=\"cubew\"><i class=\"orb\"></i><i class=\"orb o2\"></i><div class=\"cube\">' + em.slice(0, 6).map(function (e, i) { return '<div class=\"f' + (i + 1) + '\">' + e + '</div>'; }).join('') + '</div></div>';\n    } else {\n      sc.innerHTML = '<div class=\"stk\">' + [0, 1, 2].map(function (i) { var x = it[i] || {}; return '<div class=\"sc3 s' + i + '\"><div class=\"em\">' + esc(x.emoji || em[i]) + '</div><b>' + esc(x.name || '') + '</b><small>' + (x.price != null && x.price !== '' ? money(x.price) : '') + '</small></div>'; }).join('') + '<span class=\"chip3 c1\">' + esc(h.chips[0]) + '</span><span class=\"chip3 c2\">' + esc(h.chips[1]) + '</span></div>';\n    }\n  }\n\n  /* ---------- catalogue ---------- */\n  function cats() { var c = ['All']; items.forEach(function (i) { if (i.category && c.indexOf(i.category) < 0) c.push(i.category); }); return c; }\n  var CTA = { cart: 'Add', book: 'Book', enquire: 'Enquire' };\n  function cardHTML(it, i) {\n    var art = it.image ? '<img src=\"' + esc(it.image) + '\" alt=\"\">' : '<span class=\"em\">' + esc(it.emoji || '⭐') + '</span>';\n    var meta = (it.meta && it.meta.length) ? '<div class=\"mt\">' + it.meta.map(function (m) { return '<span>' + esc(m) + '</span>'; }).join('') + '</div>' : '';\n    var price = (it.price != null && it.price !== '') ? money(it.price) + (it.per ? '<small> /' + esc(it.per) + '</small>' : '') : '';\n    return '<article class=\"card3 tl rv\" style=\"--d:' + Math.min(i, 8) * .05 + 's\" data-id=\"' + esc(it.id) + '\"><div class=\"thumb\">' + (it.badge ? '<span class=\"bdg\">' + esc(it.badge) + '</span>' : '') + art + '</div><div class=\"cb\"><small>' + esc(it.category || '') + '</small><h3>' + esc(it.name) + '</h3><p>' + esc(it.desc || '') + '</p>' + meta + '<div class=\"cr\"><b class=\"pr\">' + price + '</b><button class=\"b3d\" data-open=\"' + esc(it.id) + '\">' + CTA[CONFIG.mode] + '</button></div></div></article>';\n  }\n  function renderCatalog() {\n    $('#chips').innerHTML = cats().map(function (c) { return '<button class=\"ch' + (c === cat ? ' on' : '') + '\" data-c=\"' + esc(c) + '\">' + esc(c) + '</button>'; }).join('');\n    var list = items.filter(function (i) { return (cat === 'All' || i.category === cat) && (!q || (i.name + ' ' + (i.desc || '') + ' ' + (i.category || '')).toLowerCase().indexOf(q) > -1); });\n    $('#grid').innerHTML = list.length ? list.map(cardHTML).join('') : '<p class=\"empty\">Nothing found. Try another category or search.</p>';\n    reveal(); tilt();\n  }\n  $('#chips').addEventListener('click', function (e) { var b = e.target.closest('.ch'); if (b) { cat = b.dataset.c; renderCatalog(); } });\n  $('#q').addEventListener('input', function () { q = this.value.trim().toLowerCase(); renderCatalog(); });\n  function byId(id) { return items.filter(function (i) { return String(i.id) === String(id); })[0]; }\n  $('#grid').addEventListener('click', function (e) {\n    var b = e.target.closest('[data-open]'), c = e.target.closest('.card3'); var id = b ? b.dataset.open : (c && c.dataset.id);\n    if (!id) return; var it = byId(id); if (!it) return;\n    if (b && CONFIG.mode === 'cart' && !(it.sizes && it.sizes.length) && !(it.colors && it.colors.length)) { addCart(it); return; }\n    openItem(it);\n  });\n\n  /* ---------- item window ---------- */\n  function openItem(it) {\n    var art = it.image ? '<img src=\"' + esc(it.image) + '\" alt=\"\">' : esc(it.emoji || '⭐');\n    var opts = '';\n    if (CONFIG.mode === 'cart') {\n      if (it.sizes && it.sizes.length) opts += '<select id=\"oSize\">' + it.sizes.map(function (s) { return '<option>' + esc(s) + '</option>'; }).join('') + '</select>';\n      if (it.colors && it.colors.length) opts += '<select id=\"oColor\">' + it.colors.map(function (s) { return '<option>' + esc(s) + '</option>'; }).join('') + '</select>';\n      opts += '<div style=\"margin-top:8px\"><button class=\"b3d\" id=\"oAdd\">Add to cart — ' + money(it.price) + '</button></div>';\n    } else if (CONFIG.mode === 'book') {\n      opts = '<button class=\"b3d\" id=\"oBook\">' + esc(DATA.form.cta || 'Book now') + '</button>';\n    } else {\n      opts = '<div class=\"fg\" id=\"oEnq\" style=\"margin-top:8px\"><div class=\"f w\"><label>Your name</label><input id=\"eN\"></div><div class=\"f w\"><label>Phone or email</label><input id=\"eP\"></div><div class=\"f w\"><label>Message</label><textarea id=\"eM\">I am interested in: ' + esc(it.name) + '</textarea></div><div class=\"f w\"><button class=\"b3d\" id=\"oSend\">Send enquiry</button></div></div>';\n    }\n    $('#mbody').innerHTML = '<div class=\"big\">' + art + '</div><div><small style=\"color:var(--muted)\">' + esc(it.category || '') + '</small><h3>' + esc(it.name) + '</h3><div class=\"d\">' + esc(it.desc || '') + '</div>' + ((it.meta && it.meta.length) ? '<div class=\"mt\" style=\"margin-bottom:12px\">' + it.meta.map(function (m) { return '<span>' + esc(m) + '</span>'; }).join('') + '</div>' : '') + '<b class=\"pr\" style=\"display:block;font-size:1.5rem;margin-bottom:12px\">' + (it.price != null && it.price !== '' ? money(it.price) + (it.per ? '<small> /' + esc(it.per) + '</small>' : '') : '') + '</b>' + opts + '</div>';\n    $('#mdl').classList.add('on');\n    var a = $('#oAdd'); if (a) a.onclick = function () { addCart(it, ($('#oSize') || {}).value, ($('#oColor') || {}).value); $('#mdl').classList.remove('on'); };\n    var bk = $('#oBook'); if (bk) bk.onclick = function () { $('#mdl').classList.remove('on'); var s = $('#bookForm [name=item]'); if (s) s.value = it.name; $('#book').scrollIntoView({ behavior: 'smooth' }); };\n    var sd = $('#oSend'); if (sd) sd.onclick = function () { send(CONFIG.brand + ' — enquiry: ' + it.name, ['Name: ' + $('#eN').value, 'Contact: ' + $('#eP').value, 'Message: ' + $('#eM').value], function () { $('#mdl').classList.remove('on'); }); };\n  }\n  $('#mdl').addEventListener('click', function (e) { if (e.target === this || e.target.closest('.x')) this.classList.remove('on'); });\n  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { $('#mdl').classList.remove('on'); $('#drw').classList.remove('on'); } });\n\n  /* ---------- cart ---------- */\n  function addCart(it, size, color) {\n    var k = [it.id, size || '', color || ''].join('|');\n    cart[k] = cart[k] || { id: it.id, size: size || '', color: color || '', qty: 0 }; cart[k].qty++; saveCart(); toast('Added: ' + it.name);\n  }\n  function saveCart() { try { localStorage.setItem(CK, JSON.stringify(cart)); } catch (e) { } var n = 0; Object.keys(cart).forEach(function (k) { n += cart[k].qty; }); $$('[data-cc]').forEach(function (e) { e.textContent = n; e.hidden = !n; }); renderCart(); }\n  function cartRows() { return Object.keys(cart).map(function (k) { var c = cart[k], it = byId(c.id); return it ? { k: k, it: it, c: c } : null; }).filter(Boolean); }\n  function renderCart() {\n    var rows = cartRows(), tot = 0;\n    $('#dl').innerHTML = rows.length ? rows.map(function (r) { tot += r.it.price * r.c.qty; return '<div class=\"dli\"><div class=\"em\">' + esc(r.it.emoji || '⭐') + '</div><div><b>' + esc(r.it.name) + '</b><br><small>' + [r.c.size, r.c.color].filter(Boolean).join(' · ') + '</small><div class=\"qt\"><button data-q=\"-1\" data-k=\"' + esc(r.k) + '\">−</button><span>' + r.c.qty + '</span><button data-q=\"1\" data-k=\"' + esc(r.k) + '\">+</button></div></div><b>' + money(r.it.price * r.c.qty) + '</b></div>'; }).join('') : '<p class=\"empty\">Your cart is empty.</p>';\n    $('#tot').innerHTML = '<span>Total</span><span>' + money(tot) + '</span>'; $('#ck').hidden = !rows.length;\n  }\n  $('#dl').addEventListener('click', function (e) { var b = e.target.closest('[data-q]'); if (!b) return; var c = cart[b.dataset.k]; c.qty += +b.dataset.q; if (c.qty < 1) delete cart[b.dataset.k]; saveCart(); });\n  $('#ck').addEventListener('click', function () {\n    var rows = cartRows(), total = 0;\n    var lines = rows.map(function (r) { total += r.it.price * r.c.qty; return '• ' + r.c.qty + ' × ' + r.it.name + ([r.c.size, r.c.color].filter(Boolean).length ? ' (' + [r.c.size, r.c.color].filter(Boolean).join(', ') + ')' : '') + ' — ' + money(r.it.price * r.c.qty); });\n    lines.push('', 'Total: ' + money(total));\n    if (CONFIG.checkoutUrl) { window.open(CONFIG.checkoutUrl, '_blank'); return; }   // e.g. a Stripe / Lemon Squeezy payment link\n    send(CONFIG.brand + ' — new order', lines, function () { cart = {}; saveCart(); $('#drw').classList.remove('on'); });\n  });\n  $$('[data-cartopen]').forEach(function (b) { b.addEventListener('click', function () { renderCart(); $('#drw').classList.add('on'); }); });\n  $('#drw').addEventListener('click', function (e) { if (e.target === this || e.target.closest('.x')) this.classList.remove('on'); });\n\n  /* ---------- forms (booking / join / ask the pharmacist ...) ---------- */\n  function renderForm(box, spec, id) {\n    box.innerHTML = '<h3>' + esc(spec.title) + '</h3><p class=\"s\">' + esc(spec.sub) + '</p><form id=\"' + id + '\" novalidate><div class=\"fg\">' + spec.fields.map(function (f) {\n      var inp = f.type === 'select' ? '<select name=\"' + f.name + '\">' + f.options.map(function (o) { return '<option>' + esc(o) + '</option>'; }).join('') + '</select>'\n        : f.type === 'textarea' ? '<textarea name=\"' + f.name + '\"></textarea>' : '<input name=\"' + f.name + '\" type=\"' + (f.type || 'text') + '\">';\n      return '<div class=\"f' + (f.wide ? ' w' : '') + '\"><label>' + esc(f.label) + '</label>' + inp + '</div>';\n    }).join('') + '<div class=\"f w\"><button class=\"b3d\" type=\"submit\">' + esc(spec.button) + '</button></div></div><div class=\"fm\" role=\"status\"></div></form>';\n    var form = box.querySelector('form');\n    form.onsubmit = function (e) {\n      e.preventDefault(); var fm = form.querySelector('.fm'), lines = [], bad = false;\n      spec.fields.forEach(function (f) { var v = form.querySelector('[name=\"' + f.name + '\"]').value.trim(); if (f.required && !v) bad = true; lines.push(f.label + ': ' + v); });\n      fm.className = 'fm' + (bad ? ' err' : ''); if (bad) { fm.textContent = 'Please fill in the required fields.'; return; }\n      fm.textContent = ''; send(CONFIG.brand + ' — ' + spec.title, lines, function () { form.reset(); fm.textContent = 'Thank you! We will contact you shortly.'; });\n    };\n  }\n  function renderExtras() {\n    var ex = 